create or replace function public.create_job_backend(p_user_id uuid,p_job_id text,p_tenant_id varchar,p_business_id uuid,p_title text,p_company_name text,p_category text,p_location text,p_job_type text,p_salary_range text,p_description text,p_requirements text) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_role text; begin if p_user_id is null or p_user_id <> auth.uid() then raise exception 'AUTH_MISMATCH'; end if; if p_job_id is null or length(trim(p_job_id))<1 then raise exception 'JOB_ID_REQUIRED'; end if; select upper(role) into v_role from user_memberships where user_id=auth.uid() and tenant_id::text=p_tenant_id::text and business_id=p_business_id and status='ACTIVE' limit 1; if v_role is null or v_role not in ('OWNER','BUSINESS_OWNER','ADMIN','MANAGER','SERVICE_PROVIDER','STAFF') then raise exception 'ACTIVE_BUSINESS_MEMBERSHIP_REQUIRED'; end if; if coalesce(trim(p_title),'')='' or coalesce(trim(p_company_name),'')='' then raise exception 'JOB_FIELDS_REQUIRED'; end if; insert into jobs(id,owner_user_id,tenant_id,business_id,title,company_name,category,location,job_type,salary_range,description,requirements,is_active) values(p_job_id,auth.uid(),p_tenant_id,p_business_id,trim(p_title),trim(p_company_name),nullif(trim(p_category),''),nullif(trim(p_location),''),nullif(trim(p_job_type),''),nullif(trim(p_salary_range),''),nullif(trim(p_description),''),nullif(trim(p_requirements),''),true); return jsonb_build_object('ok',true,'job_id',p_job_id); end; $$; revoke execute on function public.create_job_backend(uuid,text,varchar,uuid,text,text,text,text,text,text,text,text) from public,anon,authenticated; grant execute on function public.create_job_backend(uuid,text,varchar,uuid,text,text,text,text,text,text,text,text) to authenticated;
